7	/**
8	 * A graphical view of the simulation grid.
9	 * The view displays a colored rectangle for each location 
10	 * representing its contents. It uses a default background color.
11	 * Colors for each type of species can be defined using the
12	 * setColor method.
13	 *
14	 * @version 01.03.22
15	 */
16	public class SimulatorView extends JFrame implements SimulationObserver
17	{
18	    // Colors used for empty locations.
19	    private static final Color EMPTY_COLOR = Color.white;
20	
21	    // Color used for objects that have no defined color.
22	    private static final Color UNKNOWN_COLOR = Color.gray;
23	
24	    private final String STEP_PREFIX = "Step: ";
25	    private final String TIME_PREFIX = "Time: ";
26	    private final String WEATHER_PREFIX = "Weather: ";
27	    private final String POPULATION_PREFIX = "Population: ";
28	    private JLabel stepLabel, population, infoLabel, timeLabel, weatherLabel;
29	    private FieldView fieldView;
30	    
31	    // A map for storing colors for participants in the simulation
32	    private Map<Class, Color> colors;
33	    // A statistics object computing and storing simulation information
34	    private FieldStats stats;
35	
36	    /**
37	     * Create a view of the given width and height.
38	     * @param height The simulation's height.
39	     * @param width  The simulation's width.
40	     */
41	    public SimulatorView(int height, int width) {
42	        stats = new FieldStats();
43	        colors = new LinkedHashMap<>();
44	
45	        setTitle("Australian Outback Simulation");
46	        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
47	        infoLabel = new JLabel("  ", JLabel.CENTER);
48	        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
49	        timeLabel = new JLabel(TIME_PREFIX, JLabel.CENTER);
50	        weatherLabel = new JLabel (WEATHER_PREFIX, JLabel.CENTER);
51	        
52	        setLocation(100, 50);
53	        
54	        fieldView = new FieldView(height, width);
55	
56	        Container contents = getContentPane();
57	        
58	        JPanel infoPane = new JPanel(new BorderLayout());
59	            infoPane.add(stepLabel, BorderLayout.WEST);
60	            infoPane.add(infoLabel, BorderLayout.CENTER);
61	            infoPane.add(timeLabel, BorderLayout.EAST);
62	            infoPane.add(weatherLabel, BorderLayout.CENTER);
63	        contents.add(infoPane, BorderLayout.NORTH);
64	        contents.add(fieldView, BorderLayout.CENTER);
65	        contents.add(population, BorderLayout.SOUTH);
66	        pack();
67	        setVisible(true);
68	    }
69	    
70	    /**
71	     * Define a color to be used for a given class of animal.
72	     * @param animalClass The animal's Class object.
73	     * @param color The color to be used for the given class.
74	     */
75	    public void setColor(Class animalClass, Color color)
76	    {
77	        colors.put(animalClass, color);
78	    }
79	
80	    public void onColorRegistered(Class<?> entityClass, Color color) {
81	        setColor(entityClass, color);
82	    }
83	
84	    /**
85	     * Display a short information label at the top of the window.
86	     */
87	    public void setInfoText(String text)
88	    {
89	        infoLabel.setText(text);
90	    }
91	
92	    /**
93	     * @return The color to be used for a given class of animal.
94	     */
95	    private Color getColor(Class animalClass) {
96	        Color col = colors.get(animalClass);
97	        if(col == null) {
98	            // no color defined for this class
99	            return UNKNOWN_COLOR;
100	        }
101	        else {
102	            return col;
103	        }
104	    }
105	
106	    /**
107	     * Show the current status of the field.
108	     * @param step Which iteration step it is.
109	     * @param field The field whose status is to be displayed.
110	     */
111	    public void showStatus(int step, Field field, int time, String weather) {
112	        if(!isVisible()) {
113	            setVisible(true);
114	        }
115	            
116	        stepLabel.setText(STEP_PREFIX + step);
117	        timeLabel.setText(TIME_PREFIX + time + ":00");
118	        weatherLabel.setText(WEATHER_PREFIX + weather);
119	        stats.reset();
120	        
121	        fieldView.preparePaint();
122	
123	        for(int row = 0; row < field.getDepth(); row++) {
124	            for(int col = 0; col < field.getWidth(); col++) {
125	                Object animal = field.getObjectAt(row, col);
126	                if(animal != null) {
127	                    stats.incrementCount(animal.getClass());
128	                    fieldView.drawMark(col, row, getColor(animal.getClass()));
129	                }
130	                else {
131	                    fieldView.drawMark(col, row, EMPTY_COLOR);
132	                }
133	            }
134	        }
135	        stats.countFinished();
136	
137	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
138	        fieldView.repaint();
139	    }
140	
141	    /**
142	     * Determine whether the simulation should continue to run.
143	     * @return true If there is more than one species alive.
144	     */
145	    public boolean isViable(Field field)
146	    {
147	        return stats.isViable(field);
148	    }
149	    
150	    /**
151	     * Provide a graphical view of a rectangular field. This is 
152	     * a nested class (a class defined inside a class) which
153	     * defines a custom component for the user interface. This
154	     * component displays the field.
155	     * This is rather advanced GUI stuff - you can ignore this 
156	     * for your project if you like.
157	     */
158	    private class FieldView extends JPanel {
159	        private final int GRID_VIEW_SCALING_FACTOR = 6;
160	
161	        private int gridWidth, gridHeight;
162	        private int xScale, yScale;
163	        Dimension size;
164	        private Graphics g;
165	        private Image fieldImage;
166	
167	        /**
168	         * Create a new FieldView component.
169	         */
170	        public FieldView(int height, int width) {
171	            gridHeight = height;
172	            gridWidth = width;
173	            size = new Dimension(0, 0);
174	        }
175	
176	        /**
177	         * Tell the GUI manager how big we would like to be.
178	         */
179	        public Dimension getPreferredSize() {
180	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
181	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
182	        }
183	
184	        /**
185	         * Prepare for a new round of painting. Since the component
186	         * may be resized, compute the scaling factor again.
187	         */
188	        public void preparePaint() {
189	            if(! size.equals(getSize())) {  // if the size has changed...
190	                size = getSize();
191	                fieldImage = fieldView.createImage(size.width, size.height);
192	                g = fieldImage.getGraphics();
193	
194	                xScale = size.width / gridWidth;
195	                if(xScale < 1) {
196	                    xScale = GRID_VIEW_SCALING_FACTOR;
197	                }
198	                yScale = size.height / gridHeight;
199	                if(yScale < 1) {
200	                    yScale = GRID_VIEW_SCALING_FACTOR;
201	                }
202	            }
203	        }
204	        
205	        /**
206	         * Paint on grid location on this field in a given color.
207	         */
208	        public void drawMark(int x, int y, Color color) {
209	            g.setColor(color);
210	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
211	        }
212	
213	        /**
214	         * The field view component needs to be redisplayed. Copy the
215	         * internal image to screen.
216	         */
217	        public void paintComponent(Graphics g) {
218	            if(fieldImage != null) {
219	                Dimension currentSize = getSize();
220	                if(size.equals(currentSize)) {
221	                    g.drawImage(fieldImage, 0, 0, null);
222	                }
223	                else {
224	                    // Rescale the previous image.
225	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
226	                }
227	            }
228	        }
229	    }
230	}
